import React from 'react'

function RandomPokemonRerollButton() {
  const DAILY_KEY = 'dailyPokemon'

  // Generate a new random Pokémon image
  const rerollPokemon = () => {
    const randomNumber = Math.floor(Math.random() * 10) + 1
    const imagePath = `/Pictures/Pokemon_${randomNumber}.png` // Assuming images are in /public/Pictures/

    // Save the new Pokémon image without checking the date
    localStorage.setItem(DAILY_KEY, JSON.stringify({ imagePath }))

    // Optionally, reload the page to reflect the updated image
    window.location.reload()
  }

  return (
    <div className='p-8 text-center'>
      <button
        onClick={rerollPokemon}
        className='px-4 py-2 bg-blue-light text-white rounded-lg hover:bg-blue-dark'
      >
        Reroll Pokémon
      </button>
    </div>
  )
}

export default RandomPokemonRerollButton
